import React from 'react';
import { Routes, Route } from "react-router-dom";
import { useAuth } from './context/AuthContext';

// Pages
import LoginPage from './pages/auth/LoginPage';
import HomePage from './pages/HomePage';
import AddPetPage from './pages/shelter/AddPetPage';
import EditPetPage from './pages/shelter/EditPetPage';
import PetDetailsPage from './pages/PetDetailsPage';
import InboxPage from './pages/InboxPage'; // 1. IMPORT THIS ✅

const App = () => {
    const { user, loading } = useAuth();

    if (loading) {
        return <div style={{display:'flex', justifyContent:'center', marginTop:'50px'}}>Loading PetPal...</div>;
    }

    return (
        <Routes>
            {!user ? (
                <Route path="*" element={<LoginPage />} />
            ) : (
                <>
                    <Route path="/" element={<HomePage />} />
                    <Route path="/add-pet" element={<AddPetPage />} />
                    <Route path="/edit-pet/:id" element={<EditPetPage />} />
                    <Route path="/pet/:id" element={<PetDetailsPage />} />

                    {/* 2. ADD THE INBOX ROUTE HERE ✅ */}
                    <Route path="/inbox" element={<InboxPage />} />

                    <Route path="*" element={<HomePage />} />
                </>
            )}
        </Routes>
    );
};

export default App;
